//! Cross-language check: a PHC hash generated by the Go baseline must verify.

#[test]
fn a_hash_generated_by_the_go_baseline_verifies() {
    let Ok(hash) = std::env::var("GO_ARGON2_HASH") else {
        // Only the interop CI job sets this.
        return;
    };

    assert!(
        wildtoken::auth::credential::verify_admin_token(&hash, "interop-admin-token"),
        "the Go-generated hash did not verify"
    );
    assert!(!wildtoken::auth::credential::verify_admin_token(
        &hash,
        "interop-admin-token-2"
    ));

    let ours = wildtoken::auth::credential::hash_admin_token("interop-admin-token").unwrap();
    assert!(
        ours.starts_with("$argon2id$v=19$m=19456,t=2,p=1$"),
        "unexpected Rust PHC shape: {ours}"
    );
}
